 5	import type { Sample } from "./validate.ts";
 6	import { ValidationError, validateSample } from "./validate.ts";
 7	
 8	/**
 9	 * Parse one wire line into a Sample.
10	 *
11	 * Wire format is three whitespace-separated fields: `<series> <value> <at>`.
12	 * A trailing timestamp may be omitted, in which case `fallbackAt` is used.
13	 */
14	export function parseSample(line: string, fallbackAt?: number): Sample {
15	  const fields = line.trim().split(/\s+/);
16	  if (fields.length < 2 || fields.length > 3) {
17	    throw new ValidationError(
18	      "line",
19	      `expected "<series> <value> [<at>]", got ${fields.length} field(s)`,
20	    );
21	  }
22	  const [series, rawValue, rawAt] = fields;
23	
24	  const at = rawAt === undefined ? fallbackAt : Number(rawAt);
25	  if (at === undefined) {
26	    throw new ValidationError("at", "omitted, and no fallback timestamp given");
27	  }
28	
29	  return validateSample({ series, value: Number(rawValue), at });
30	}
31	
32	/**
33	 * A bounded FIFO buffer between the wire and the store.
34	 *
35	 * Overflow drops the *oldest* sample, not the newest: under sustained pressure
36	 * a recent picture beats a stale one.
37	 */
38	export class IngestQueue {
39	  private buffer: Sample[] = [];
40	  private dropped = 0;
41	  private readonly capacity: number;
42	
43	  constructor(capacity: number) {
44	    if (!Number.isInteger(capacity) || capacity <= 0) {
45	      throw new RangeError("capacity must be a positive integer");
46	    }
47	    this.capacity = capacity;
48	  }
49	
50	  push(sample: Sample): void {
51	    this.buffer.push(sample);
52	    while (this.buffer.length > this.capacity) {
53	      this.buffer.shift();
54	      this.dropped += 1;
55	    }
56	  }
57	
58	  /** Take everything buffered so far, leaving the queue empty. */
59	  drain(): Sample[] {
60	    const taken = this.buffer;
61	    this.buffer = [];
62	    return taken;
63	  }
64	
65	  size(): number {
66	    return this.buffer.length;
67	  }
68	
69	  /** How many samples overflow has discarded since construction. */
70	  droppedCount(): number {
71	    return this.dropped;
72	  }
73	}

