 1	import assert from "node:assert/strict";
 2	import { describe, it } from "node:test";
 3	
 4	import { IngestQueue, parseSample } from "../src/ingest.ts";
 5	import { createService } from "../src/index.ts";
 6	import { ValidationError } from "../src/validate.ts";
 7	
 8	describe("parseSample", () => {
 9	  it("parses the three-field wire form", () => {
10	    assert.deepEqual(parseSample("cpu.load 0.5 1000"), {
11	      series: "cpu.load",
12	      value: 0.5,
13	      at: 1000,
14	    });
15	  });
16	
17	  it("falls back to the supplied timestamp when `at` is omitted", () => {
18	    assert.deepEqual(parseSample("cpu.load 0.5", 7000), {
19	      series: "cpu.load",
20	      value: 0.5,
21	      at: 7000,
22	    });
23	  });
24	
25	  it("rejects a line with too many fields", () => {
26	    assert.throws(() => parseSample("cpu.load 1 2 3"), ValidationError);
27	  });
28	
29	  it("rejects an omitted timestamp with no fallback", () => {
30	    assert.throws(() => parseSample("cpu.load 1"), /at:/);
31	  });
32	});
33	
34	describe("IngestQueue", () => {
35	  it("drains what was pushed, in order", () => {
36	    const queue = new IngestQueue(4);
37	    queue.push({ series: "a", value: 1, at: 1 });
38	    queue.push({ series: "a", value: 2, at: 2 });
39	    assert.equal(queue.size(), 2);
40	    assert.deepEqual(
41	      queue.drain().map((s) => s.value),
42	      [1, 2],
43	    );
44	    assert.equal(queue.size(), 0);
45	  });
46	
47	  it("drops the oldest sample on overflow", () => {
48	    const queue = new IngestQueue(2);
49	    for (const value of [1, 2, 3]) {
50	      queue.push({ series: "a", value, at: value });
51	    }
52	    assert.deepEqual(
53	      queue.drain().map((s) => s.value),
54	      [2, 3],
55	    );
56	    assert.equal(queue.droppedCount(), 1);
57	  });
58	
59	  it("refuses a non-positive capacity", () => {
60	    assert.throws(() => new IngestQueue(0), RangeError);
61	  });
62	});
63	
64	describe("the ingest path", () => {
65	  it("buffers a posted sample and lands it on the next tick", () => {
66	    const service = createService(
67	      { windowMs: 1_000, retentionMs: 60_000, maxSamples: 4 },
68	      { now: () => 1_000 },
69	    );
70	
71	    const reply = service.router.dispatch("POST", "/samples", "cpu.load 0.5 1000");
72	    assert.equal(reply.status, 202);
73	    assert.deepEqual(
74	      service.store.series(),
75	      [],
76	      "a posted sample is buffered, not stored — the store is only current after a tick",
77	    );
78	
79	    service.tick();
80	    assert.deepEqual(service.store.series(), ["cpu.load"]);
81	  });
82	});

